-- Tier 3 lists for the tier-token exchange at Overlord Runthak (14392) and Major Mattingly (14394),
-- opened through npc_coa_tier_token_vendor like the T1/T2 lists 91000001-91000008.
--
-- Items: the 17 Tier 3 sets that both vendors sell in the Exiles DB export of 2026-09-13
-- (npc_vendor 14392/14394; item sets 405, 521, 523-530, 1222, 1531 and the alternate sets
-- 2001-2005), with each difficulty's clone from item_template (Normal +0, Heroic +300000,
-- Mythic +1300000, Ascended +200000; alternate sets 15xxxxx, 18xxxxx, 28xxxxx, 17xxxxx).
-- Costs: one token of the slot and difficulty, as the client ItemExtendedCost.dbc defines them:
-- Normal 40700-40707, Heroic 40800-40807, Mythic 49800-49807, Ascended 40900-40907 (head,
-- shoulder, chest, wrist, hands, waist, legs, feet); rings 40799, 40999, 49999 and 40899.
-- The four armor lists hold 136 pieces each and the rings get their own list, because one
-- vendor list shows at most 150 items (MAX_VENDOR_ITEMS).
-- T3 Normal: virtual vendor 91000009
DELETE FROM `npc_vendor` WHERE `entry` = 91000009;
-- T3 Heroic: virtual vendor 91000010
DELETE FROM `npc_vendor` WHERE `entry` = 91000010;
-- T3 Mythic: virtual vendor 91000011
DELETE FROM `npc_vendor` WHERE `entry` = 91000011;
-- T3 Ascended: virtual vendor 91000012
DELETE FROM `npc_vendor` WHERE `entry` = 91000012;
-- T3 Rings: virtual vendor 91000013
DELETE FROM `npc_vendor` WHERE `entry` = 91000013;
